        <span class="temp t${i}" id="temp">${city.tempC}</span>
        <span class="cond">${city.condition}</span>
        <span class="meta">Humidity ${city.humidity}% - Wind ${city.wind} km/h</span>
      </div>`, { width: 0.24, position: [xs[i], 0.26, -0.04], rotationY: rots[i] });
    root.add(panel.object3D);
    cardPanels.push(panel);
  }

  const detailPanel = ui(`
    <style>
      .bar { width: 540px; flex-direction: column; gap: 8px; padding-top: 14px; padding-bottom: 14px; padding-left: 18px; padding-right: 18px; border-radius: 16px; background-color: #1f2228; }
