      .title { color: #ffffff; font-size: 26px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="bar">
      <div class="row">
        <span class="title" id="detailTitle">Weather Dashboard - Today</span>
        <button class="btn" id="units"><span class="btn-text" id="unitsLabel">Show Fahrenheit</span></button>
      </div>
      <span class="body" id="detailBody">Sample data for today. Press the sun, rain or snow icon above for details.</span>
    </div>`, { width: 0.52, position: [0, 0.09, 0.12], rotationY: 0 });
  root.add(detailPanel.object3D);

  function makeCloud(mat) {
    const cloud = new THREE.Group();
    const parts = [
      [0, 0.006, 0, 0.026],
      [-0.022, 0, 0, 0.019],
      [0.022, 0.001, 0, 0.020]
    ];
    for (let i = 0; i < parts.length; i++) {
      const m = new THREE.Mesh(new THREE.SphereGeometry(parts[i][3], 24, 16), mat);
      m.position.set(parts[i][0], parts[i][1], parts[i][2]);
      m.scale.set(1, 0.85, 1);
      cloud.add(m);
    }
    return cloud;
  }

  function makeDisc() {
    const d = new THREE.Mesh(
      new THREE.CircleGeometry(0.05, 32),
      new THREE.MeshStandardMaterial({ color: 0x22262e, roughness: 0.9 })
    );
