  const hydrogenGeo = new THREE.SphereGeometry(0.021, 24, 14);

  // Faint ghost template showing the bent water shape
  const ghostGroup = new THREE.Group();
  ghostGroup.name = 'GhostTemplate';
  root.add(ghostGroup);

  const ghostO = new THREE.Mesh(
    oxygenGeo,
